function countZeroSum(arr) {
  const seen = new Map([[0, 1]]);                    // prefix sum -> times seen so far
  let sum = 0, count = 0;
  for (const x of arr) {
    sum += x;
    count += seen.get(sum) ?? 0;                      // each earlier equal sum = one zero-sum subarray
    seen.set(sum, (seen.get(sum) ?? 0) + 1);
  }
  return count;
}

long countZeroSum(int[] arr) {
    Map<Long, Integer> seen = new HashMap<>();          // prefix sum -> times seen so far
    seen.put(0L, 1);
    long sum = 0, count = 0;
    for (int x : arr) {
        sum += x;
        count += seen.getOrDefault(sum, 0);              // each earlier equal sum = one zero-sum subarray
        seen.merge(sum, 1, Integer::sum);
    }
    return count;
}

long long countZeroSum(vector<int>& arr) {
    unordered_map<long long, int> seen{{0, 1}};        // prefix sum -> times seen so far
    long long sum = 0, count = 0;
    for (int x : arr) {
        sum += x;
        auto it = seen.find(sum);
        if (it != seen.end()) count += it->second;      // each earlier equal sum = one zero-sum subarray
        seen[sum]++;
    }
    return count;
}
